const page = String.raw`<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="A month of giving across UCL, inspired by Movember and welcoming fundraising for a wider range of charities and causes."><title>UCL Societies’ November Giving Leaderboard</title>
<style>
/* Open font licences are retained with the embedded font software.
${embeddedDesign.fontLicence}
*/
@font-face{font-family:Anton;src:url("${embeddedDesign.anton}") format("woff2");font-weight:400;font-style:normal;font-display:swap}
@font-face{font-family:Overpass;src:url("${embeddedDesign.overpass}") format("woff2");font-weight:100 900;font-style:normal;font-display:swap}
/* UCL-inspired purple campaign block; Movember-inspired Anton / Overpass typography.
   DESIGN_VARIANCE: 5; MOTION_INTENSITY: 1; VISUAL_DENSITY: 4.
   Square edges throughout. No campaign animations or background refresh. */
:root{color-scheme:light dark;--background:#fcfcfd;--surface:#f2eef6;--ink:#242027;--muted:#615c66;--line:#d9d4df;--accent:#7028ad;--tint:#eee4f7;--skeleton:#e2dce9;--relegation-background:#fff0f0;--relegation-ink:#9d252b;--campaign:#321d4d;--stripe:#9933ff;--campaign-text:#fcf9ff;--campaign-muted:#e5daef;font-family:Overpass,Arial,sans-serif;color:var(--ink);background:var(--background);font-synthesis:none}
*{box-sizing:border-box}body{margin:0}a{color:inherit;text-underline-offset:4px}a:hover{color:var(--accent)}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}button{font:inherit;cursor:pointer}button:active{transform:translateY(1px)}[hidden]{display:none!important}
.masthead{border-bottom:1px solid var(--line)}.masthead-inner{max-width:1160px;height:76px;margin:auto;padding:0 40px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font-size:23px;font-weight:750;letter-spacing:-.04em;text-decoration:none}.campaign-label{font-size:13px;color:var(--muted)}main{max-width:1160px;margin:0 auto;padding:32px 40px 36px}
.campaign{display:grid;grid-template-columns:1.15fr 1fr;margin-bottom:28px}.campaign-copy{padding:34px 36px;border-left:8px solid var(--stripe);background:var(--campaign);color:var(--campaign-text)}h1{margin:0;font-family:Anton,Impact,"Arial Narrow",sans-serif;font-weight:400;font-size:clamp(42px,4.6vw,58px);line-height:1.12;text-transform:uppercase;letter-spacing:-.02em}.campaign-copy p{max-width:42ch;margin:20px 0 0;font-size:17px;line-height:1.55;color:var(--campaign-muted)}.campaign-photo{position:relative;min-width:0;overflow:hidden;background:var(--campaign)}.campaign-photo img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:54% 50%}
.campaign-intro{max-width:90ch;margin:0 0 36px;font-size:16px;line-height:1.7;color:var(--muted)}.campaign-intro p{margin:0}.campaign-intro .competition-note{margin-top:12px}.campaign-intro a{color:var(--accent)}h2{margin:0 0 18px;font-size:24px;line-height:1.3;font-weight:600;letter-spacing:-.02em}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:18px}.sorts{display:flex;gap:24px}.sorts button{border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);padding:10px 0 9px;font-size:15px;line-height:1.4;font-weight:600;white-space:nowrap}.sorts button:hover{color:var(--accent)}.sorts button[aria-pressed=true]{border-bottom-color:var(--accent);color:var(--accent)}.summary{margin:0;font-size:13px;line-height:1.5;color:var(--muted)}
.table-wrap{border:1px solid var(--line);border-top:2px solid var(--accent);background:var(--background)}table{width:100%;border-collapse:collapse;table-layout:fixed;text-align:left}col.rank-column{width:72px}col.raised-column{width:180px}col.members-column{width:150px}th{padding:16px 20px;color:var(--muted);font-size:12px;font-weight:600;background:var(--surface)}th:first-child,td:first-child{padding-left:20px}td{padding:24px 20px;border-top:1px solid var(--line);vertical-align:top}.numeric{text-align:right;font-variant-numeric:tabular-nums}.rank{padding-top:29px;font-size:16px;font-weight:600;color:var(--muted)}.leader .rank{color:var(--accent)}.relegation{background:var(--relegation-background)}.relegation .rank{color:var(--relegation-ink)}.relegation td:first-child{box-shadow:inset 3px 0 0 var(--relegation-ink)}.relegation-label{display:block;margin-top:7px;font-size:11px;font-weight:600;line-height:1.4;color:var(--relegation-ink)}.team-name{display:block;width:fit-content;max-width:100%;font-weight:600;line-height:1.4;font-size:18px;text-decoration-thickness:1px;overflow-wrap:anywhere}.sub{display:block;margin-top:5px;font-size:13px;line-height:1.6;color:var(--muted);overflow-wrap:anywhere}.value{display:block;font-size:26px;font-weight:600;line-height:1.2;letter-spacing:-.025em;overflow-wrap:anywhere}.numeric .sub{font-size:11px}.skeleton{display:inline-block;min-width:50px;height:26px;background:var(--skeleton)}.noncurrent .team-name{color:var(--muted)}.status-note{color:var(--muted);font-size:12px;line-height:1.6;margin-top:6px;display:block}.empty{text-align:center;padding:36px 20px;color:var(--ink);font-size:16px;font-weight:550;line-height:1.6}.empty-description{display:block;max-width:52ch;margin:8px auto 0;font-size:13px;font-weight:400;line-height:1.7;color:var(--muted)}@media(hover:hover){tbody tr:not(.relegation):hover{background:var(--surface)}}
.message{margin:0 0 20px;font-size:14px;line-height:1.65;color:var(--ink)}.message:empty,.ranking-note:empty{display:none}.ranking-note{font-size:13px;line-height:1.6;color:var(--muted);margin:16px 0 0}footer{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:16px 24px;padding-top:22px;font-size:13px;line-height:1.7;color:var(--muted)}footer p{margin:0}details{margin-left:auto;max-width:58ch}summary{cursor:pointer;width:fit-content;margin-left:auto;color:var(--ink);text-underline-offset:4px}summary:hover{text-decoration:underline}details[open]{width:100%}details[open] summary{margin-bottom:12px}details p{line-height:1.8}.photo-credit{flex-basis:100%;font-size:11px}.admin-link{flex-basis:100%;width:fit-content;font-size:12px}caption{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
@media(prefers-color-scheme:dark){:root{--background:#17151a;--surface:#242028;--ink:#f2eef5;--muted:#bcb4c4;--line:#49404f;--accent:#c69af0;--tint:#34243f;--skeleton:#46374f;--relegation-background:#342026;--relegation-ink:#ffadb3}}
@media(max-width:767px){.masthead-inner{height:64px;padding:0 20px}.brand{font-size:21px}.campaign-label{font-size:12px}main{padding:20px 20px 28px}.campaign{grid-template-columns:1fr;margin-bottom:22px}.campaign-intro{font-size:15px;line-height:1.65;margin-bottom:28px}.campaign-copy{padding:24px 22px;border-left-width:5px}h1{font-size:clamp(36px,9.2vw,52px);line-height:1.12}.campaign-copy p{font-size:15px;line-height:1.55;margin-top:16px}.campaign-photo{order:-1;height:96px}.campaign-photo img{object-position:50% 55%}h2{font-size:22px;margin-bottom:10px}.toolbar{align-items:flex-start;flex-direction:column;gap:12px;margin-bottom:15px}.sorts{gap:22px}.sorts button{padding:9px 0 8px;font-size:14px}.summary{font-size:12px}col.rank-column{width:34px}col.raised-column{width:90px}col.members-column{width:76px}th{padding:12px 8px;font-size:11px;line-height:1.45}th:first-child,td:first-child{padding-left:0}th:last-child,td:last-child{padding-right:0}td{padding:20px 8px}.rank{padding-top:24px;font-size:13px}.team-name{font-size:16px;line-height:1.4}.sub{font-size:11px;margin-top:5px}.value{font-size:23px;letter-spacing:-.035em}.numeric .sub{font-size:10px}.skeleton{min-width:36px;height:23px}footer{flex-direction:column;gap:12px;padding-top:18px;font-size:12px}details,summary{margin-left:0}details{max-width:100%}.admin-link,.photo-credit{flex-basis:auto}.empty{padding:28px 14px;font-size:15px}.empty-description{font-size:12px}}
</style></head><body>
<div class="masthead"><div class="masthead-inner"><a class="brand" href="/">UCL Societies</a><span class="campaign-label">November giving</span></div></div>
<main><header class="campaign"><div class="campaign-copy"><h1>November Giving Leaderboard</h1><p>UCL societies coming together for the causes they care about.</p></div><div class="campaign-photo"><img src="${embeddedDesign.portico}" alt="UCL's Portico illuminated for its bicentenary" decoding="async" fetchpriority="high"></div></header>
<section class="campaign-intro" aria-label="About November Giving"><p>November is our month for giving. Taking inspiration from <a href="https://movember.com/about-us" target="_blank" rel="noopener noreferrer">Movember</a>’s focus on men’s health, we’re bringing UCL societies together to raise funds for a wider range of charities and causes. Everyone is welcome to take part.</p><p class="competition-note">There’s a little friendly competition, too: the committee of the society that raises the least will take on a forfeit.</p></section>
<p id="errors" class="message" role="alert"></p>
<section aria-labelledby="standings-heading"><h2 id="standings-heading">Society standings</h2>
<div class="toolbar"><div class="sorts" role="group" aria-label="Rank teams by"><button type="button" id="sort-raised" aria-pressed="true">Money raised</button><button type="button" id="sort-members" aria-pressed="false">Team members</button></div><p id="summary" class="summary" role="status" aria-live="polite">Loading societies…</p></div>
<div class="table-wrap"><table><caption>Society fundraising rankings. Equal values share a rank.</caption><colgroup><col class="rank-column"><col><col class="raised-column"><col class="members-column"></colgroup><thead><tr><th scope="col">Rank</th><th scope="col">Society</th><th scope="col" class="numeric">Raised</th><th scope="col" class="numeric">Team members</th></tr></thead><tbody id="rows" aria-busy="true"><tr><td colspan="4" class="empty">Loading the leaderboard…</td></tr></tbody></table></div>
<p id="ranking-note" class="ranking-note"></p>
</section>
<footer><p>Reload the page to update totals.</p><details><summary>How the rankings work</summary><p>Movember shows the current campaign total. JustGiving totals exclude Gift Aid. Money ranks within each currency, and tied totals share a rank. Only published team-member counts enter the team-size ranking. Unavailable or stale readings are left unranked. The source platform controls when new donations appear.</p></details><a href="/admin/login" id="admin-link" class="admin-link" hidden>Manage teams</a><p class="photo-credit">Campus photograph: <a href="https://www.ucl.ac.uk/" target="_blank" rel="noopener noreferrer">UCL</a></p></footer>
</main><script>
(() => {
 ${canonicalUrl.toString()}
 ${rankRows.toString()}
 const tbody=document.getElementById('rows'),summary=document.getElementById('summary'),errors=document.getElementById('errors');
 let metric='raised',rows=[],busy=false,listFailed=false;
 const money=d=>new Intl.NumberFormat('en-GB',{style:'currency',currency:d.currency,maximumFractionDigits:d.amountMinor%100?2:0}).format(d.amountMinor/100);
 function platformOf(value){return new URL(value).hostname==='uk.movember.com'?'movember':'justgiving';}
 function cell(tr,value,className){const td=document.createElement('td');if(className)td.className=className;if(value!==undefined)td.textContent=value;tr.append(td);return td;}
 function sub(parent,value,className='sub'){const el=document.createElement('span');el.className=className;el.textContent=value;parent.append(el);return el;}
 function render(){
  tbody.replaceChildren();tbody.setAttribute('aria-busy',String(busy));
  const ordered=rankRows(rows,metric);
  for(const row of ordered){
   const d=row.data,tr=document.createElement('tr'),relegated=!busy&&row.isBottom;tr.className=relegated?'relegation':row.status!=='fresh'?'noncurrent':row.rank===1?'leader':'';
   const rank=cell(tr,busy?'':row.rank===null?'-':String(row.rank),'rank');if(busy||row.rank===null)rank.setAttribute('aria-label','Not ranked');
   const team=cell(tr),link=document.createElement('a');link.className='team-name';link.textContent=row.name||(d?d.name:new URL(row.url).pathname);link.href=row.url;link.target='_blank';link.rel='noopener noreferrer';team.append(link);
   sub(team,row.platform==='movember'?'Movember':'JustGiving');
   if(relegated)sub(team,'Relegation zone','relegation-label');
   if(row.status==='stale')sub(team,'Previous reading. Not ranked.','status-note');
   if(row.error)sub(team,row.error,'status-note');
   const raised=cell(tr,undefined,'numeric'),members=cell(tr,undefined,'numeric');
   if(row.status==='loading'&&!d){
    sub(raised,'','value skeleton').setAttribute('aria-label','Loading amount');
    sub(members,'','value skeleton').setAttribute('aria-label','Loading team members');
   }else{
    sub(raised,d?money(d):'N/A','value');
    if(d&&d.giftAidMinor!==null)sub(raised,'+ '+money({...d,amountMinor:d.giftAidMinor})+' Gift Aid');
    sub(members,d&&d.peopleLabel==='Team members'&&d.people!==null?new Intl.NumberFormat('en-GB').format(d.people):'N/A','value');
    if(d&&d.peopleLabel!=='Team members')sub(members,d.people===null?'Not published':new Intl.NumberFormat('en-GB').format(d.people)+' '+d.peopleLabel.toLowerCase());
    if(d&&d.peopleLabel==='Team members'&&d.people===null)sub(members,'Not published');
   }
   tbody.append(tr);
  }
  if(!rows.length){const tr=document.createElement('tr'),td=cell(tr,listFailed?'The leaderboard is unavailable. Reload the page to try again.':'No societies listed yet.','empty');td.colSpan=4;if(!listFailed)sub(td,'Society fundraising pages will appear here once they’ve been added.','empty-description');tbody.append(tr);}
  const fresh=rows.filter(x=>x.status==='fresh').length;
  summary.textContent=busy?'Loading totals… '+rows.filter(x=>x.status!=='loading').length+' of '+rows.length:listFailed?'Could not load societies.':rows.length+' '+(rows.length===1?'society':'societies')+' taking part'+(fresh<rows.length?' ('+fresh+' available)':'');
  const currencies=[...new Set(rows.filter(x=>x.status==='fresh').map(x=>x.data.currency))];
  document.getElementById('ranking-note').textContent=metric==='raised'&&currencies.length>1?'Different currencies are ranked separately.':metric==='members'?'Only published team-member counts receive a team-size rank.':'';
 }
 async function loadLeaderboard(){
  busy=true;errors.textContent='';
  let teams;
  try{
   const response=await fetch('/api/teams',{cache:'no-store'});
   const list=await response.json();if(!response.ok)throw new Error(list.error||'Could not load the society list.');
   teams=list.teams;document.getElementById('admin-link').hidden=!list.canEdit;
  }catch(error){
   listFailed=true;busy=false;errors.textContent=error.message;render();return;
  }
  rows=teams.map(team=>({url:team.url,name:team.name,platform:platformOf(team.url),status:'loading',data:null,error:null}));
  render();
  let index=0;
  async function next(){
   while(index<rows.length){
    const row=rows[index++];
    try{
     const response=await fetch('/api/totals?platform='+row.platform+'&url='+encodeURIComponent(row.url),{cache:'no-store'});
     const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not read this page. Reload to try again.');
     row.data=data;row.status=data.status;row.error=data.error||null;
    }catch(error){row.status='error';row.error=error.message;}
    render();
   }
  }
  try{await Promise.all(Array.from({length:Math.min(4,rows.length)},next));}
  finally{busy=false;render();}
 }
 for(const [id,value] of [['sort-raised','raised'],['sort-members','members']])document.getElementById(id).addEventListener('click',()=>{metric=value;document.getElementById('sort-raised').setAttribute('aria-pressed',String(metric==='raised'));document.getElementById('sort-members').setAttribute('aria-pressed',String(metric==='members'));render();});
 loadLeaderboard();
})();
</script></body></html>
`;

